static G ReadGeo(MeshRenderer r){var f=r.GetComponent<MeshFilter>();var data=Read(f.sharedMesh);var uv=Field<Vector2[][]>(data,"uv");if(uv[0]==null)return null;var mat=r.sharedMaterial;string path=AssetDatabase.GetAssetPath(mat.HasProperty("_BaseMap")?mat.GetTexture("_BaseMap"):mat.mainTexture);if(string.IsNullOrEmpty(path)||!File.Exists(path))return null;if(!textures.TryGetValue(path,out var texture)){texture=new Texture2D(2,2);texture.LoadImage(File.ReadAllBytes(path));textures[path]=texture;}Texture2D surface=null;if(mat.HasProperty("_CitySurfaceMap")){string packedPath=AssetDatabase.GetAssetPath(mat.GetTexture("_CitySurfaceMap"));if(!string.IsNullOrEmpty(packedPath)&&File.Exists(packedPath)){if(!textures.TryGetValue(packedPath,out surface)){surface=new Texture2D(2,2);surface.LoadImage(File.ReadAllBytes(packedPath));textures[packedPath]=surface;}}}var g=new G{surface=surface,r=r,original=f.sharedMesh,material=mat,p=Field<Vector3[]>(data,"p").Select(f.transform.TransformPoint).ToArray(),uv=uv[0],ids=Field<int[]>(data,"ids"),b=r.bounds,tex=texture};var map=new Dictionary<string,P>();for(int k=0;k<g.ids.Length;k+=3){var a=g.p[g.ids[k]];var b=g.p[g.ids[k+1]];var c=g.p[g.ids[k+2]];var cross=Vector3.Cross(b-a,c-a);if(cross.magnitude<.5f||Mathf.Abs(cross.normalized.y)>.002f)continue;var n=cross.normalized;if(Vector3.Dot((a+b+c)/3-g.b.center,n)<0)n=-n;n.y=0;n.Normalize();float d=Vector3.Dot(a,n);string key=Mathf.RoundToInt(n.x*100)+","+Mathf.RoundToInt(n.z*100)+","+Mathf.RoundToInt(d*20);if(!map.TryGetValue(key,out var plane)){plane=new P{g=g,n=n,t=Vector3.Cross(Vector3.up,n).normalized,d=d};map[key]=plane;}plane.tris.Add(k);foreach(var v in new[]{a,b,c}){float x=Vector3.Dot(v,plane.t);plane.x0=Mathf.Min(plane.x0,x);plane.x1=Mathf.Max(plane.x1,x);plane.y0=Mathf.Min(plane.y0,v.y);plane.y1=Mathf.Max(plane.y1,v.y);}}g.planes=map.Values.Where(p=>p.x1-p.x0>2.6f&&p.y1-p.y0>1.5f).OrderByDescending(p=>(p.x1-p.x0)*(p.y1-p.y0)).Take(24).ToList();return g;}
static bool Hit(G g,Vector3 origin,Vector3 dir,out float distance){distance=float.PositiveInfinity;for(int k=0;k<g.ids.Length;k+=3){var a=g.p[g.ids[k]];var e=g.p[g.ids[k+1]]-a;var f=g.p[g.ids[k+2]]-a;var q=Vector3.Cross(dir,f);float det=Vector3.Dot(e,q);if(Mathf.Abs(det)<.000001f)continue;var v=origin-a;float u=Vector3.Dot(v,q)/det;if(u<0||u>1)continue;var c=Vector3.Cross(v,e);float w=Vector3.Dot(dir,c)/det;if(w<0||u+w>1)continue;float t=Vector3.Dot(f,c)/det;if(t>.001f&&t<distance)distance=t;}return !float.IsInfinity(distance);}
static bool UV(P plane,Vector3 point,out Vector2 uv){var g=plane.g;float x=Vector3.Dot(point,plane.t),y=point.y;foreach(int k in plane.tris){int i0=g.ids[k],i1=g.ids[k+1],i2=g.ids[k+2];var a=new Vector2(Vector3.Dot(g.p[i0],plane.t),g.p[i0].y);var b=new Vector2(Vector3.Dot(g.p[i1],plane.t),g.p[i1].y);var c=new Vector2(Vector3.Dot(g.p[i2],plane.t),g.p[i2].y);float det=(b.y-c.y)*(a.x-c.x)+(c.x-b.x)*(a.y-c.y);if(Mathf.Abs(det)<.000001f)continue;float u=((b.y-c.y)*(x-c.x)+(c.x-b.x)*(y-c.y))/det;float v=((c.y-a.y)*(x-c.x)+(a.x-c.x)*(y-c.y))/det;if(u>=-.002f&&v>=-.002f&&u+v<=1.002f){uv=g.uv[i0]*u+g.uv[i1]*v+g.uv[i2]*(1-u-v);return true;}}uv=Vector2.zero;return false;}
static bool Blank(P plane,Vector3 center,float width,float height){var values=new List<float>();int dark=0;for(int y=0;y<7;y++)for(int x=0;x<9;x++){var point=center+plane.t*((x/8f-.5f)*(width+.6f))+Vector3.up*((y/6f-.5f)*(height+.5f));if(!UV(plane,point,out var uv)){fitRejected++;return false;}if(plane.g.surface!=null&&plane.g.surface.GetPixelBilinear(Mathf.Repeat(uv.x,1),Mathf.Repeat(uv.y,1)).b>.25f){blankRejected++;return false;}var color=plane.g.tex.GetPixelBilinear(Mathf.Repeat(uv.x,1),Mathf.Repeat(uv.y,1));float l=color.r*.299f+color.g*.587f+color.b*.114f;values.Add(l);if(l<.14f)dark++;if(dark>8){blankRejected++;return false;}}float avg=values.Average();float sd=Mathf.Sqrt(values.Average(v=>(v-avg)*(v-avg)));if(avg<.20f||sd>.105f){blankRejected++;return false;}
// Reject physical frames, vents and ledges projecting through the artwork rectangle.
var g=plane.g;float tx=Vector3.Dot(center,plane.t);for(int k=0;k<g.ids.Length;k+=3){var a=g.p[g.ids[k]];var b=g.p[g.ids[k+1]];var c=g.p[g.ids[k+2]];float da=Vector3.Dot(a,plane.n)-plane.d,db=Vector3.Dot(b,plane.n)-plane.d,dc=Vector3.Dot(c,plane.n)-plane.d;float front=Mathf.Max(da,Mathf.Max(db,dc));if(front<.07f||Mathf.Min(da,Mathf.Min(db,dc))>1.5f)continue;float x0=Mathf.Min(Vector3.Dot(a,plane.t),Mathf.Min(Vector3.Dot(b,plane.t),Vector3.Dot(c,plane.t))),x1=Mathf.Max(Vector3.Dot(a,plane.t),Mathf.Max(Vector3.Dot(b,plane.t),Vector3.Dot(c,plane.t)));float y0=Mathf.Min(a.y,Mathf.Min(b.y,c.y)),y1=Mathf.Max(a.y,Mathf.Max(b.y,c.y));if(x1>tx-width/2-.15f&&x0<tx+width/2+.15f&&y1>center.y-height/2-.15f&&y0<center.y+height/2+.15f){fitRejected++;return false;}}return true;}
static bool RoadView(S site){foreach(var road in roads.Where(r=>{var d=r-site.p;d.y=0;return d.magnitude<85&&d.magnitude>4&&Vector3.Dot(d.normalized,site.n)>.50f;}).OrderBy(r=>(r-site.p).sqrMagnitude).Take(8)){var camera=new Vector3(road.x,29.5f,road.z);var dir=(site.p-camera).normalized;float distance=Vector3.Distance(camera,site.p);bool blocked=props.Any(b=>b.IntersectRay(new Ray(camera,dir),out float t)&&t<distance-.2f);foreach(var g in geos){if(!g.b.IntersectRay(new Ray(camera,dir),out var near)||near>distance)continue;if(Hit(g,camera,dir,out var hit)&&hit<distance-.12f){blocked=true;break;}}if(!blocked){var right=Vector3.Cross(Vector3.up,site.n);foreach(var offset in new[]{right*site.w*.48f+Vector3.up*site.h*.48f,-right*site.w*.48f+Vector3.up*site.h*.48f,right*site.w*.48f-Vector3.up*site.h*.48f,-right*site.w*.48f-Vector3.up*site.h*.48f}){var corner=site.p+offset;var ray=(corner-camera).normalized;float len=Vector3.Distance(camera,corner);if(props.Any(b=>b.IntersectRay(new Ray(camera,ray),out float t)&&t<len-.2f)){blocked=true;break;}foreach(var geo in geos){if(geo.b.IntersectRay(new Ray(camera,ray),out var nearCorner)&&nearCorner<len&&Hit(geo,camera,ray,out var hitCorner)&&hitCorner<len-.12f){blocked=true;break;}}if(blocked)break;}if(!blocked){site.camera=camera;return true;}}}blockedRejected++;return false;}

static void Run(){
var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");
if(!scene.isLoaded)throw new Exception("City scene is not loaded");
if(scene.GetRootGameObjects().Any(g=>g.name=="Gangster Neon Road Facing Wall Art"))throw new Exception("Already installed; use verification instead");
Directory.CreateDirectory(D+"Meshes");Directory.CreateDirectory(D+"Prefabs");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeGangsterNeonAtlas");
File.Copy(scene.path,"FinalEnvironmentRoadBackup/BeforeGangsterNeonAtlas/Scene.unity",true);
var old=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="City Road Facing Neon Wall Art");
var rs=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).Where(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh&&(!old||!r.transform.IsChildOf(old.transform))).ToArray();
props=rs.Where(r=>AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh).Contains("Roads Props")&&r.bounds.size.y>2&&r.bounds.size.x>1&&r.bounds.size.z>1&&r.bounds.size.x<25&&r.bounds.size.z<25).Select(r=>r.bounds).ToList();
var candidates=rs.Where(r=>r.sharedMaterials.Length==1&&r.sharedMaterial&&r.sharedMaterial.name.StartsWith("Building")&&r.bounds.size.y>1.7f&&r.bounds.size.y<180&&r.bounds.size.x>3&&r.bounds.size.z>3&&r.bounds.size.x<220&&r.bounds.size.z<220&&!r.name.Contains("Circus")&&!r.name.Contains("Casino")&&!r.name.Contains("Parking")&&!r.name.ToLower().Contains("building52")).OrderBy(r=>r.bounds.center.x).ThenBy(r=>r.bounds.center.z).ToArray();
foreach(var r in candidates){var g=ReadGeo(r);if(g!=null)geos.Add(g);}
var controller=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();roads=controller.streetLightPositions;
var oldMat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/CityBuildingSigns/City Shared Sign Atlas.mat");
foreach(var r in rs.Where(r=>r.sharedMaterial==oldMat)){var data=Read(r.GetComponent<MeshFilter>().sharedMesh);var p=Field<Vector3[]>(data,"p").Select(r.transform.TransformPoint).ToArray();var ids=Field<int[]>(data,"ids");for(int k=0;k<ids.Length;k+=3){var b=new Bounds(p[ids[k]],Vector3.zero);b.Encapsulate(p[ids[k+1]]);b.Encapsulate(p[ids[k+2]]);b.Expand(1.6f);signs.Add(b);}}
int[] used=new int[36];int processed=0;
foreach(var g in geos){int count=0;var nearbySigns=signs.Where(b=>{var expanded=g.b;expanded.Expand(5);return expanded.Intersects(b);}).ToArray();
foreach(var plane in g.planes){if(count>=8)break;float span=plane.x1-plane.x0,high=plane.y1-plane.y0;if(plane.y1<29.2f)continue;int planeCount=0;int max=Mathf.Clamp(Mathf.FloorToInt(span/(high<4.5f?16:23)),1,5);
float size=high<3.6f?Mathf.Clamp(high*.64f,1.2f,2.0f):Mathf.Clamp(high*.26f,2.8f,6.5f);
foreach(float factor in new[]{1f,.72f,.52f}){if(planeCount>=max||count>=8)break;float h=size*factor,w=h;if(w>span-.8f||h>high-.65f||h<1.2f)continue;
foreach(float y in new[]{Mathf.Max(plane.y0,27.6f)+h/2+.5f,plane.y0+high*.38f,plane.y0+high*.60f,plane.y0+high*.78f}){if(planeCount>=max||count>=8)break;if(y-h/2<28.0f||y+h/2>plane.y1-.3f||y+h/2>50f)continue;
foreach(float fraction in new[]{.5f,.22f,.78f,.36f,.64f,.10f,.90f}){if(planeCount>=max||count>=8)break;float x=Mathf.Lerp(plane.x0,plane.x1,fraction);if(x-w/2<plane.x0+.3f||x+w/2>plane.x1-.3f)continue;
var center=plane.n*plane.d+plane.t*x+Vector3.up*y;var b=new Bounds(center+plane.n*.07f,new Vector3(Mathf.Abs(plane.t.x)*w+.25f,h+.25f,Mathf.Abs(plane.t.z)*w+.25f));if(nearbySigns.Any(s=>s.Intersects(b)))continue;var spacing=b;spacing.Expand(new Vector3(5,2.5f,5));if(sites.Any(s=>s.b.Intersects(spacing)))continue;
if(!Blank(plane,center,w,h))continue;var site=new S{g=g,p=center+plane.n*.065f,n=plane.n,w=w,h=h,b=b};if(!RoadView(site))continue;
var close=sites.Where(s=>Vector3.Distance(s.p,site.p)<75).Select(s=>s.art).ToArray();site.art=Enumerable.Range(0,36).OrderBy(i=>close.Contains(i)?1000+used[i]:used[i]).ThenBy(i=>(i*17+processed*7)%36).First();sites.Add(site);used[site.art]++;planeCount++;count++;
}}}}
processed++;if(processed%15==0)File.WriteAllText(Report+"Progress.txt","Audited "+processed+"/"+geos.Count+" buildings; supported road-facing blank-wall prefab sites="+sites.Count);
}
if(sites.Count<100)throw new Exception("Coverage insufficient: "+sites.Count+"; old installation retained");
AssetDatabase.ImportAsset(D+"Gangster Neon 36 Atlas.png",ImportAssetOptions.ForceSynchronousImport);
var ti=(TextureImporter)AssetImporter.GetAtPath(D+"Gangster Neon 36 Atlas.png");ti.textureType=TextureImporterType.Default;ti.alphaSource=TextureImporterAlphaSource.FromInput;ti.alphaIsTransparency=true;ti.sRGBTexture=true;ti.mipmapEnabled=true;ti.npotScale=TextureImporterNPOTScale.None;ti.wrapMode=TextureWrapMode.Clamp;ti.filterMode=FilterMode.Trilinear;ti.anisoLevel=2;ti.maxTextureSize=2048;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.isReadable=false;
foreach(string platform in new[]{"Android","iPhone"}){var ps=ti.GetPlatformTextureSettings(platform);ps.overridden=true;ps.maxTextureSize=2048;ps.format=TextureImporterFormat.ASTC_6x6;ps.compressionQuality=80;ti.SetPlatformTextureSettings(ps);}ti.SaveAndReimport();
var shader=Shader.Find("City/Mobile Gangster Neon Decals");if(!shader||ShaderUtil.ShaderHasError(shader))throw new Exception("Neon shader failed");
var mat=new Material(shader){name="Gangster Neon Shared Atlas",enableInstancing=true};mat.SetTexture("_Atlas",AssetDatabase.LoadAssetAtPath<Texture2D>(D+"Gangster Neon 36 Atlas.png"));mat.SetFloat("_NightGlow",1.55f);mat.SetFloat("_Cutoff",.16f);AssetDatabase.CreateAsset(mat,D+"Gangster Neon Shared Atlas.mat");
var prefabs=new GameObject[36];for(int i=0;i<36;i++){
float u=(i%6)/6f,v=1-(i/6+1)/6f,pad=.6f/1254f;var mesh=new Mesh{name="Neon "+(i+1).ToString("00")+" "+names[i]};mesh.vertices=new[]{new Vector3(-.5f,-.5f,0),new Vector3(.5f,-.5f,0),new Vector3(.5f,.5f,0),new Vector3(-.5f,.5f,0)};mesh.normals=Enumerable.Repeat(Vector3.forward,4).ToArray();mesh.uv=new[]{new Vector2(u+1/6f-pad,v+pad),new Vector2(u+pad,v+pad),new Vector2(u+pad,v+1/6f-pad),new Vector2(u+1/6f-pad,v+1/6f-pad)};mesh.triangles=new[]{0,1,2,0,2,3};mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,D+"Meshes/"+mesh.name+".asset");
var go=new GameObject(mesh.name);go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=mat;r.shadowCastingMode=ShadowCastingMode.Off;r.receiveShadows=false;r.lightProbeUsage=LightProbeUsage.Off;r.reflectionProbeUsage=ReflectionProbeUsage.Off;var lod=go.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.025f,new Renderer[]{r})});lod.RecalculateBounds();lod.size=1.25f;GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.OccludeeStatic);prefabs[i]=PrefabUtility.SaveAsPrefabAsset(go,D+"Prefabs/"+mesh.name+".prefab");UnityEngine.Object.DestroyImmediate(go);
}
var root=new GameObject("Gangster Neon Road Facing Wall Art");int num=0;
foreach(var group in sites.GroupBy(s=>s.g)){var parent=new GameObject("Wall Art - "+group.Key.r.name);parent.transform.SetParent(root.transform,false);parent.transform.position=group.Key.b.center;
foreach(var s in group){var go=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[s.art],scene);go.transform.SetParent(parent.transform,true);go.transform.position=s.p;go.transform.rotation=Quaternion.LookRotation(s.n,Vector3.up);go.transform.localScale=new Vector3(s.w,s.h,s.w);go.name="Neon "+(s.art+1).ToString("00")+" - "+names[s.art];PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);num++;}}
foreach(var g in geos)if(g.r.GetComponent<MeshFilter>().sharedMesh!=g.original||g.r.sharedMaterial!=g.material)throw new Exception("Native building changed");
if(old)UnityEngine.Object.DestroyImmediate(old);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
File.WriteAllLines(Report+"Placements.csv",new[]{"owner,x,y,z,nx,nz,width,height,art,cameraX,cameraY,cameraZ"}.Concat(sites.Select(s=>s.g.r.name.Replace(","," ")+","+s.p.x+","+s.p.y+","+s.p.z+","+s.n.x+","+s.n.z+","+s.w+","+s.h+","+(s.art+1)+","+s.camera.x+","+s.camera.y+","+s.camera.z)));
File.WriteAllText(Report+".txt","SUCCESS audited buildings="+geos.Count+" prefab instances="+num+" decorated building mesh groups="+sites.Select(s=>s.g).Distinct().Count()+" triangles="+num*2+". Exactly 36 mesh assets / 36 reusable prefab assets, one shared approved atlas, one GPU-instanced material, no new lights/colliders. Original city geometry/materials unchanged. Old wall art replaced. Rejected texture="+blankRejected+" support="+fitRejected+" visibility="+blockedRejected+" shader errors="+ShaderUtil.ShaderHasError(shader)+"\n"+string.Join("\n",Enumerable.Range(0,36).Select(i=>(i+1)+" "+names[i]+"="+used[i])));
foreach(var t in textures.Values)UnityEngine.Object.DestroyImmediate(t);textures.Clear();
}
